import{_ as o,o as e,c as r,a2 as l}from"./chunks/framework.BEUshCVJ.js";const c=JSON.parse('{"title":"识别与提示质量","description":"","frontmatter":{},"headers":[],"relativePath":"zh/troubleshooting/quality.md","filePath":"zh/troubleshooting/quality.md","lastUpdated":1793020206000}'),n={name:"zh/troubleshooting/quality.md"};function i(s,t,a,g,h,u){return e(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="识别与提示质量" tabindex="-1">识别与提示质量 <a class="header-anchor" href="#识别与提示质量" aria-label="Permalink to &quot;识别与提示质量&quot;">​</a></h1><p>本页用于没有出现提示、不该出现时出现提示，或识别出错字的情况。</p><h2 id="no-hints" tabindex="-1">对方提问了但没有出现提示 <a class="header-anchor" href="#no-hints" aria-label="Permalink to &quot;对方提问了但没有出现提示 {#no-hints}&quot;">​</a></h2><p><strong>可能原因</strong></p><ol><li>拾取已暂停，或系统声音没有电平。</li><li>开启了 <strong>只提示指向我的问题</strong>，而这个问题看起来是问别人的。</li><li>问题很短或只是客套反问（“对吧？”“是吗？”），这类句子会被有意忽略。</li><li>要点生成失败或超时（<a href="/meetcue/zh/troubleshooting/error-codes#mc-llm-001">MC-LLM-001</a>、<a href="/meetcue/zh/troubleshooting/error-codes#mc-llm-005">MC-LLM-005</a>）。</li><li>达到了预算上限，且选择了 <strong>暂停要点生成</strong>（<a href="/meetcue/zh/troubleshooting/error-codes#mc-bud-002">MC-BUD-002</a>）。</li></ol><p><strong>检查</strong></p><ol><li>查看面板标题栏的状态点：绿色表示正在拾取。</li><li>打开 <strong>设置 › 诊断</strong>。最近事件会显示这句话是否被识别，以及检测的判断结果。</li></ol><p><strong>解决</strong></p><ol><li>按 <code>Ctrl+Alt+Space</code> 开始拾取；电平不动请参考<a href="/meetcue/zh/troubleshooting/audio">音频与设备</a>。</li><li>如果希望每个问题都有提示，关闭 <strong>只提示指向我的问题</strong>。</li><li>出现错误码时，按错误提示中的办法处理。</li></ol><p><strong>仍未解决？</strong> <a href="/meetcue/zh/troubleshooting/diagnostics">导出诊断信息</a>并<a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">提交 Issue</a>。</p><h2 id="too-many" tabindex="-1">闲聊也出现提示 <a class="header-anchor" href="#too-many" aria-label="Permalink to &quot;闲聊也出现提示 {#too-many}&quot;">​</a></h2><p><strong>可能原因</strong></p><ol><li>检测模型对你的会议来说太弱。</li><li>多人之间互相提问，并不是问你的。</li></ol><p><strong>检查</strong></p><ol><li>点开对话中的灰色问题原文，查看识别依据。</li></ol><p><strong>解决</strong></p><ol><li>打开 <strong>设置 › 提示 › 只提示指向我的问题</strong>。</li><li>填写 <strong>我的角色</strong>，让检测知道哪些问题该由你回答。</li><li>在 <strong>设置 › 供应商与费用</strong> 中换一个更强的检测模型。</li></ol><p><strong>仍未解决？</strong> <a href="/meetcue/zh/troubleshooting/diagnostics">导出诊断信息</a>并<a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">提交 Issue</a>。</p><h2 id="recognition" tabindex="-1">人名和术语识别错误 <a class="header-anchor" href="#recognition" aria-label="Permalink to &quot;人名和术语识别错误 {#recognition}&quot;">​</a></h2><p><strong>可能原因</strong></p><ol><li>会议语言设置不对。</li><li>识别模型不认识产品名和缩写。</li><li>音量太小或噪音大。</li></ol><p><strong>检查</strong></p><ol><li>打开 <strong>设置 › 音频 › 会议语言</strong>。</li><li>有人说话时观察对话中的转写。</li></ol><p><strong>解决</strong></p><ol><li>选择实际使用的语言。同一句话里中英混说时选 <strong>中文和英文</strong>。</li><li>把议程或项目资料添加为<a href="/meetcue/zh/guide/materials">会前资料</a>，其中的关键术语会作为热词传给识别服务。</li><li>换另一家识别供应商试试：Soniox 对一句话里中英混说处理得很好。</li></ol><p><strong>仍未解决？</strong> <a href="/meetcue/zh/troubleshooting/diagnostics">导出诊断信息</a>并<a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">提交 Issue</a>。</p><h2 id="split" tabindex="-1">一个问题被切成两段 <a class="header-anchor" href="#split" aria-label="Permalink to &quot;一个问题被切成两段 {#split}&quot;">​</a></h2><p><strong>可能原因</strong></p><ol><li>说话人在问题中间停顿的时间超过了“静音多久算一句结束”的设定。</li></ol><p><strong>检查</strong></p><ol><li>查看是否有两个相邻的问题块，第一个在半句话处结束。</li></ol><p><strong>解决</strong></p><ol><li>调大 <strong>设置 › 音频 › 高级 › 静音多久算一句结束</strong>，例如从 700 毫秒调到 1000 毫秒。提示会稍晚一点出现。</li></ol><p><strong>仍未解决？</strong> <a href="/meetcue/zh/troubleshooting/diagnostics">导出诊断信息</a>并<a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">提交 Issue</a>。</p>',34)])])}const m=o(n,[["render",i]]);export{c as __pageData,m as default};
